export function SlashCommand({
  commandQuery = "{{commandQuery}}",
  selectedOption = "{{selectedOption}}",
  accent = "{{accent}}",
  showDescriptions = {{showDescriptions}},
  radius = {{radius}},
}) {
  const items = [
    { key: "heading", name: "Heading", desc: "Big section title" },
    { key: "image", name: "Image", desc: "Upload or embed a picture" },
    { key: "table", name: "Table", desc: "Rows and columns of data" },
    { key: "divider", name: "Divider", desc: "A horizontal rule" },
  ];
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, maxWidth: 300 }}>
      <p style={{ margin: "0 0 8px" }}>Typing <span style={{ fontFamily: "ui-monospace, monospace", background: "#24143010", padding: "2px 6px", borderRadius: 4 }}>/{commandQuery}</span></p>
      <ul role="listbox" aria-label="Insert block" style={{ listStyle: "none", margin: 0, padding: 6, background: "#fff", boxShadow: "0 10px 24px rgba(36,20,48,.16)", borderRadius: radius }}>
        {items.map((item) => (
          <li key={item.key} role="option" style={{ display: "flex", alignItems: "baseline", gap: 8, padding: "8px 10px", borderRadius: 6,
            background: item.key === selectedOption ? accent : "transparent" }}>
            <span style={{ fontWeight: 600, fontSize: 14 }}>{item.name}</span>
            {showDescriptions && <span style={{ fontSize: 12, color: "#241430aa" }}>{item.desc}</span>}
          </li>
        ))}
      </ul>
    </div>
  );
}
